"""#####

    /// Catalogue of features the user can leave off the map, generated from mkgmap's own
    /// rule lines by `kmap hideable`. See Assets/hideable.txt.
    static let hideableCatalogue =
#####"""
# What kmap can leave off the map. Generated by kmap from the rule lines in
# its own materialized points file, so every substitution is exact.
#
# Hiding removes a rule, not data: rebuild without the box ticked and it is back.
# Format:  @@ <category>   then  [id] <name>   then 'tag: key=value'   then one
# 'points: <exact line>' per rule the entry covers.
#
# The quoted 'points:' lines are mkgmap's own, from its default style, and are
# GPL v2 like the rest of it. They are here because a substitution has to name
# the line it replaces exactly. See NOTICE.md.

@@ Amenities
[amenity-arts_centre] Arts centre
tag: amenity=arts_centre
points: amenity=arts_centre [0x2d01 resolution 24]
[amenity-atm] Atm
tag: amenity=atm
points: amenity=atm [0x2f06 resolution 24 continue]
[amenity-bank] Bank
tag: amenity=bank
points: amenity=bank [0x2f06 resolution 24]
[amenity-bar] Bar
tag: amenity=bar
points: amenity=bar [0x2d02 resolution 24 continue]
[amenity-bench] Bench
tag: amenity=bench
points: amenity=bench [0x6605 resolution 24 continue]
[amenity-biergarten] Biergarten
tag: amenity=biergarten
points: amenity=biergarten [0x2d02 resolution 24]
[amenity-border_control] Border control
tag: amenity=border_control
points: amenity=border_control | barrier=border_control [0x3006 resolution 20]
[amenity-bus_station] Bus station
tag: amenity=bus_station
points: amenity=bus_station [0x2f08 resolution 23]
[amenity-cafe] Cafe
tag: amenity=cafe
points: amenity=cafe {delete cuisine} [0x2a0e resolution 24 continue with_actions]
[amenity-car_club] Car club
tag: amenity=car_club
points: amenity=car_club [0x2f02 resolution 24]  # kmap: same key as car_rental/car_sharing
[amenity-car_rental] Car rental
tag: amenity=car_rental
points: amenity=car_rental [0x2f02 resolution 24]
[amenity-car_sharing] Car sharing
tag: amenity=car_sharing
points: amenity=car_sharing [0x2f02 resolution 24]
[amenity-car_wash] Car wash
tag: amenity=car_wash
points: amenity=car_wash [0x2f0e resolution 24]
[amenity-casino] Casino
tag: amenity=casino
points: amenity=casino [0x2d04 resolution 24]
[amenity-charging_station] Charging station
tag: amenity=charging_station
points: amenity=charging_station [0x2f1a resolution 24 default_name 'Car charging']
[amenity-cinema] Cinema
tag: amenity=cinema
points: amenity=cinema [0x2d03 resolution 24]
[amenity-college] College
tag: amenity=college
points: amenity=college [0x2c05 resolution 24]
[amenity-community_center] Community center
tag: amenity=community_center
points: amenity=community_center [0x3005 resolution 24]
[amenity-community_centre] Community centre
tag: amenity=community_centre
points: amenity=community_centre [0x3005 resolution 24]
[amenity-concert_hall] Concert hall
tag: amenity=concert_hall
points: amenity=concert_hall [0x2d01 resolution 24]  # kmap: label anchor -- the mask lied about the place
[amenity-conference_centre] Conference centre
tag: amenity=conference_centre
points: amenity=conference_centre [0x661a resolution 24]  # kmap: label anchor -- the mask lied about the place
